const addDays = (date, days) => new Date(Date.parse(`${date}T00:00:00Z`) + days * 86400000).toISOString().slice(0, 10);

function nextBusinessDay(date, holidays) {
  let next = addDays(date, 1);
  while (true) {
    const day = new Date(`${next}T00:00:00Z`).getUTCDay();
    if (day !== 0 && day !== 6 && !holidays.has(next)) return next;
    next = addDays(next, 1);
  }
}

const holidays = new Set(["2026-10-01"]);
console.log(nextBusinessDay("2026-09-30", holidays), nextBusinessDay("2026-10-02", holidays), nextBusinessDay("2026-03-04", holidays));

