const parts = new Intl.DateTimeFormat("en-US", { timeZone: "Africa/Lagos", hourCycle: "h23", weekday: "short", hour: "numeric" });

function isOpen(instant) {
  const f = Object.fromEntries(parts.formatToParts(instant).map((p) => [p.type, p.value]));
  const hour = Number(f.hour);
  return f.weekday !== "Sun" && hour >= 8 && hour < 20;
}

